#!/bin/sh -eu
echo '-------------------------------------------------------------------------------------------'
echo '[NOTE] Launching application, this will fail if you did not build the project at least once'
echo '[NOTE] Remove the launcher folder to throw away local changes'
echo '-------------------------------------------------------------------------------------------'

# Optional Felix HTTP JVM opts (e.g. virtual threads) from the CONGA local-plain
# environment. Generated by `mvn -pl devops/conga conga:generate`; absent = fast
# loop with defaults. Same file the Ansible slingslop role appends in prod.
HTTP_JAVA_OPTS=""
CONGA_HTTP_JAVA_OPTS=../devops/conga/target/configuration/local-plain/localhost/env/http-java-opts
[ -f "$CONGA_HTTP_JAVA_OPTS" ] && HTTP_JAVA_OPTS=$(cat "$CONGA_HTTP_JAVA_OPTS")

# Only attach JDWP when port 38080 is free — a stale Sling JVM holding 38080
# would otherwise cause the new JVM to abort before Sling even starts.
JDWP_OPTS=""
if ! ss -tlnp 2>/dev/null | grep -q ':38080 '; then
  JDWP_OPTS="-Xrunjdwp:transport=dt_socket,server=y,suspend=n,address=38080"
fi

export JAVA_OPTS="-XX:+UseG1GC -XX:+UseCompactObjectHeaders -XX:+UseStringDeduplication \
                  --enable-native-access=ALL-UNNAMED \
                  ${JDWP_OPTS} \
                  ${EXTRA_JAVA_OPTS:-} ${HTTP_JAVA_OPTS}"

# Sample-content is no longer baked into the feature/seed (code-only). Install
# the staged demo packages once Sling answers — always overwritten (force),
# scoped per content root, so other/user content is untouched. Backgrounded so
# it can wait while the launcher comes up in the foreground. The container/prod
# deploy has no Maven, so it keeps using src/main/container/bin/install-sample-content.sh
# instead; see install-sample-content-local.sh for why the local path differs.
( ./install-sample-content-local.sh ) &

target/dependency/org.apache.sling.feature.launcher/bin/launcher -f target/slingfeature-tmp/feature-slingslop_aggregate.json
